import { installLazyTabMountApi } from "./lazy-tab-mount.js";
import { destroyTable } from "./state.js";
import { ensureMounted } from "./mount.js";
import { reloadTable } from "./data.js";
import {
	applyPlanDeltaVisibility,
	initTable,
	onToggleDimensions,
	onTogglePlanOrDelta,
	onPeriodOrAggregateChange,
	onViewOptionsChange,
	refreshColumns,
	refreshRuntime,
} from "./table.js";
import {
	buildSavePlanPayload,
	getSelectedRows,
	saveForecastAsPlan,
} from "./selection.js";
import { buildChartData, refreshChart } from "./chart-adapter.js";
import {
	accountAllowsTask,
	buildParentAdjustmentsFromUpdates,
	getBasisForecastMap,
	getDisplayPeriods,
	isBudgetReady,
} from "./budget-tree.js";

let ready = false;

const ProjectBudget = {
	isReady() {
		return ready;
	},

	ensureMounted,

	destroy(frm) {
		destroyTable(frm);
	},

	async refresh(frm) {
		const table = await reloadTable(frm, initTable, refreshRuntime);
		refreshChart(frm);
		return table;
	},

	refreshColumns,
	applyPlanDeltaVisibility,
	onTogglePlanOrDelta,
	onToggleDimensions,
	onPeriodOrAggregateChange,
	onViewOptionsChange,
	getSelectedRows,
	buildSavePlanPayload,
	saveForecastAsPlan,
	buildChartData,
	refreshChart,

	/** Cross-app: risk reserves / WE parent-adjust (project_budget tree, no aggregatedBudget). */
	isBudgetReady,
	getDisplayPeriods,
	accountAllowsTask,
	getBasisForecastMap,
	buildParentAdjustments: buildParentAdjustmentsFromUpdates,
};

ready = true;
window.ProjectBudget = ProjectBudget;
installLazyTabMountApi();

export { ProjectBudget };
